import java.util.LinkedList;
import java.util.Queue;

public class SymmetricTree {

    // 递归解法（首选）
    public boolean isSymmetricRecursive(TreeNode root) {
        if (root == null) return true;
        return isMirror(root.left, root.right);
    }

    private boolean isMirror(TreeNode p, TreeNode q) {
        if (p == null && q == null) return true;       // 都空 → 镜像
        if (p == null || q == null) return false;       // 一边空 → 不镜像
        return p.val == q.val                           // 值相等
            && isMirror(p.left, q.right)                // 外侧配对
            && isMirror(p.right, q.left);               // 内侧配对
    }

    // 迭代解法
    public boolean isSymmetricIterative(TreeNode root) {
        if (root == null) return true;
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root.left);
        queue.offer(root.right);
        while (!queue.isEmpty()) {
            TreeNode p = queue.poll();
            TreeNode q = queue.poll();
            if (p == null && q == null) continue;       // 都空 → 跳过
            if (p == null || q == null) return false;   // 一边空
            if (p.val != q.val) return false;           // 值不等
            // 按镜像配对顺序入队
            queue.offer(p.left);
            queue.offer(q.right);
            queue.offer(p.right);
            queue.offer(q.left);
        }
        return true;
    }

    public static void main(String[] args) {
        SymmetricTree s = new SymmetricTree();
        // 示例 1: [1,2,2,3,4,4,3] → true
        TreeNode root = new TreeNode(1,
            new TreeNode(2, new TreeNode(3), new TreeNode(4)),
            new TreeNode(2, new TreeNode(4), new TreeNode(3)));
        System.out.println(s.isSymmetricRecursive(root)); // true
        System.out.println(s.isSymmetricIterative(root)); // true

        // 示例 2: [1,2,2,null,3,null,3] → false
        TreeNode root2 = new TreeNode(1,
            new TreeNode(2, null, new TreeNode(3)),
            new TreeNode(2, null, new TreeNode(3)));
        System.out.println(s.isSymmetricRecursive(root2)); // false
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val; this.left = left; this.right = right;
    }
}
